-- The claims a plan has made, so a change of its amount can reach those still DRAFT.
CREATE TABLE plan_claim (
    plan_id  BIGINT NOT NULL REFERENCES plan (id),
    claim_id BIGINT NOT NULL,
    PRIMARY KEY (plan_id, claim_id)
);
-- The sheet's notes: a text added by a user, dated by the sheet's today when it was added.
CREATE TABLE sheet_note (
    id         BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    added_on   DATE          NOT NULL,
    added_by   VARCHAR(200)  NOT NULL,
    note_text  VARCHAR(2000) NOT NULL
);
@RequestMapping("/api/sheets")
