                    sheet.getEscalateAfter(), sheet.getReviewSla(), sheet.getProofKinds(),
                    sheet.getDefaultGrade(), sheet.getScoreMid(), sheet.getScoreHigh(), sheet.isScoreLog(),
                    sheet.getMaxOpen());
        }
    }

